  "payment.failed": {
    code: 20003,
    message: "Payment failed, please try again later",
  },
  "payment.timeout": {
    code: 20004,
    message: "Payment timeout, please check payment status",
  },

  // ── General ──
  "server.error": {
    code: 50000,
    message: "Internal server error, please try again later",
  },
  "server.maintenance": {
    code: 50001,
    message: "System maintenance in progress, estimated recovery at {{time}}",
  },
};

路由中使用

// src/routes/orders.ts


export default defineRoutes((app) => {
  app.post(
    "/",
    {
      validate: {
        body: {
          productId: "string!",
          quantity: "number:1-99!",
        },
      },
      middlewares: ["auth"],
      auth: { required: true, security: "bearerAuth" },
      docs: { summary: "创建订单" },
    },
    async (req, res) => {
      const data = req.valid("body");
      const userId = req.auth?.userId;
      if (typeof userId !== "string") app.throw(401, "auth.unauthorized");

      const order = await app.services.order.create(userId, data);
      res.json(order, 201);
    },
  );
});

// src/services/order.ts



export default class OrderService {
  constructor(private app: VextApp) {}

  async create(userId: string, data: { productId: string; quantity: number }) {
    // 检查商品
    const product = await this.findProduct(data.productId);
    if (!product) {
      this.app.throw(404, "order.not_found");
    }

    // 检查数量限制
    if (data.quantity > 10) {
      this.app.throw(400, "order.limit_exceeded", { max: 10 });
    }

    // 检查余额
    const balance = await this.getBalance(userId);
    const required = product.price * data.quantity;
    if (balance < required) {
      this.app.throw(400, "balance.insufficient", { balance, required });
      // zh-CN → "余额不足，当前余额 50 元，需要 100 元"
      // en-US → "Insufficient balance. Current: 50, required: 100"
    }

    // 创建订单...
    return { orderId: randomUUID(), status: "pending" };
  }

  private async findProduct(id: string) {
    return id === "demo" ? { id, price: 10, name: "Sample Product" } : null;
  }

  private async getBalance(userId: string) {
    return 50;
  }
}

该片段在认证通过且带 productId: "demo" 时：quantity=1 返回201；quantity=6因余额50不足返回400并插值；quantity=11命中限购返回400；其他 productId 返回404。数字数量还应按业务要求限制为整数；此处仅展示与翻译有关的分支。

排查翻译未生效

现象	检查与修复	复验
总是默认语言	检查 supported 是否包含目标语言、请求上下文是否启用、Accept-Language 是否匹配	用上面的中英文 not-found 请求比较 message
返回 key 本身	检查最终键、当前与默认字典、模块命名空间及实际加载目录	访问 missing-key 与已知键对比
启动报重复来源/键	根据诊断中的两个来源消除冲突，不能依靠扩展名覆盖	重新启动并验证两个语言请求
插值变量没有替换	检查业务消息的 {{name}} 与 params，校验消息使用 {{#label}} 等上游键	请求 balance 和空对象 validated
开发修改后仍旧消息	查看重载日志是否失败，修正无效字典后重新触发或重启	重复请求，不把旧字典仍可用当作重载成功

最佳实践

1. 规划稳定的业务 code

需要按 code 区分错误时，建议为不同业务含义分配独立码；多个错误共用 HTTP 状态码并非框架禁止，但客户端无法仅凭 code 区分：

// ✅ 正确 — 不同错误使用不同 code
'user.not_found':   { code: 40001, message: '...' },
'user.email_taken': { code: 40002, message: '...' },

// 同用 400 可以工作，但客户端需结合业务上下文区分
'user.not_found':   { code: 400, message: '...' },
'user.email_taken': { code: 400, message: '...' },

2. 同步维护多语言文件

添加新的 i18n key 时，确保所有语言包同步更新。当前语言缺键时先回退到应用默认语言，两者都缺失才显示原始 message。

Review 时核对语义、key 和业务码一致性；利用已有测试覆盖语言协商、缺键回退和错误状态，不以键集合相等替代翻译质量审查。

3. 消息面向用户编写

i18n 消息最终会展示给终端用户，应使用通俗易懂的语言：

// ✅ 用户友好
{
  message: "余额不足，当前余额 {{balance}} 元";
}
{
  message: "登录已过期，请重新登录";
}

// ❌ 技术化表述
{
  message: "InsufficientBalanceException: current={{balance}}";
}
{
  message: "JWT token expired at timestamp";
}

4. 合理使用模板变量

动态信息使用模板变量，避免拼接字符串：

// ✅ 使用模板变量
{
  message: "最多购买 {{max}} 件";
}
app.throw(400, "order.limit_exceeded", { max: 10 });

// ❌ 避免拼接
app.throw(400, `最多购买 ${max} 件`); // 无法 i18n

5. i18n 是可选的

不需要 i18n 的项目完全不用创建 locales/ 目录。app.throw() 在没有语言包时直接使用原始 message 字符串，功能完全正常。

只有当你的 API 需要面向多语言客户端时，才需要配置 i18n。

