// src/routes/webhooks/stripe.ts


export default defineRoutes((app) => {
  // POST /webhooks/stripe → Stripe 事件回调
  app.post(
    "/",
    {
      bodyParser: { enabled: false },
      validate: {
        header: { "stripe-signature": "string!" },
      },
      docs: {
        summary: "Stripe Webhook 回调",
        description: "接收 Stripe 支付事件通知。需要验证签名。",
        responses: {
          200: { description: "处理成功" },
          400: { description: "签名验证失败" },
        },
      },
    },
    async (req, res) => {
      const signature = req.valid("header")["stripe-signature"];
      await app.services.payment.handleStripeWebhook(req, signature);
      res.json({ received: true });
    },
  );
});

此处 payment.handleStripeWebhook(req, signature) 是应用自己的接入契约：需通过应用插件或适配器集成提供受限的原始请求读取，再使用 Stripe SDK、签名和 endpoint secret 验证，最后处理事件及幂等。公共 VextRequest 没有通用原始流读取方法；关闭 body parser 不会自动获得原始内容，也不能使用 req.body 代替。这个片段只说明目录与文档声明，不是可直接使用的支付接入；原始 body 要求见 Stripe 官方说明。

生成的 OpenAPI 路径

以上目录结构最终自动生成以下 OpenAPI 路径。默认 Vext Docs 侧栏按路径段导航，tags 作为接口元数据保留：

OpenAPI 路径	方法	Tag	来源文件
/api/v1/users	GET	API v1	api/v1/users.ts
/api/v1/users/{id}	GET	API v1	api/v1/users.ts
/api/v1/users/{id}/orders	GET	API v1	api/v1/users/[id]/orders.ts
/api/v1/users/{id}/orders/{orderId}	GET	API v1	api/v1/users/[id]/orders.ts
/api/v1/admin/dashboard/stats	GET	API v1	api/v1/admin/dashboard.ts
/api/v1/admin/users	GET	API v1	api/v1/admin/users.ts
/api/v1/admin/users/{id}/ban	PATCH	API v1	api/v1/admin/users.ts
/webhooks/stripe	POST	Webhooks	webhooks/stripe.ts

:::tip 多级目录最佳实践

用目录层级表达 URL 结构：api/v1/admin/ 自动映射为 /api/v1/admin/ 前缀，无需手动拼接

动态参数用 [param] 目录：users/[id]/orders.ts 自动变为 /users/:id/orders，文件内的 param 校验会出现在 OpenAPI 文档中

operation tag 自动推断：路由级 docs.tags 已废弃并会被忽略；Vext 从路由 path/source 自动推断 operation tags，默认文档页仍按路径段导航

文件名即路由：无需 app.group() 或手动注册路由前缀，目录结构就是路由结构
:::

标签分组（x-tagGroups）

OpenAPI 3.x 的 tags 是一维列表。部分外部文档工具按 tags 平铺导航，可用它们支持的 x-tagGroups 扩展分组；内置 Vext Docs 使用路径树。

VextJS 只有在显式配置 openapi.tagGroups 时才会透传 x-tagGroups。内置 Vext Docs renderer 的默认侧栏主导航会优先使用 OpenAPI path segment 生成递归树，因此 x-tagGroups 只是原始 OpenAPI vendor extension 元数据，不是 Vext Docs 的导航能力。

默认行为

VextJS 默认不生成 x-tagGroups。内置 Vext Docs renderer 会使用 OpenAPI path segment 作为递归侧栏的真相源，因此自动 tag 分组并不必要，也容易生成 General / Admin 这类误导性分组。

路由级 docs.tags 已废弃并会被忽略。如果交付链路里的其他 OpenAPI 工具需要 x-tagGroups，可以在配置中显式指定 tagGroups，并确保分组里的名称匹配自动推断出的 operation tags 或全局 openapi.tags：

// src/config/default.ts
export default {
  port: 3000,
  openapi: {
    enabled: true,
    title: "My API",
    version: "1.0.0",

    // 给 OpenAPI 工具显式透传 vendor extension
    tagGroups: [
      {
        name: "Public API",
        tags: ["API v1"],
      },
      {
        name: "Integration",
        tags: ["Webhooks"],
      },
    ],

    // 可选：给自动推断的 operation tags 增加描述。
    tags: [
      { name: "API v1", description: "版本 1 API 接口" },
      { name: "Webhooks", description: "第三方回调" },
    ],
  },
};

:::warning
只有配置了 tagGroups 时，框架才会输出 x-tagGroups。请确保每个分组内的 tag 名称都能匹配 operation tag 或全局 tags 定义，避免消费该 OpenAPI 文档的工具出现未分组或不可见的标签。
:::

效果对比

默认 Vext Docs	显式 x-tagGroups
侧栏按 OpenAPI path segment 导航	OpenAPI 文档包含显式 vendor extension 元数据
/api/v1/info 保留为资源分类	Public API ▸ API v1 / Integration ▸ Webhooks
tags 作为接口元数据	仅适合下游 OpenAPI 工具明确消费 x-tagGroups

与热重载的兼容性

在 dev 模式下，热重载（soft reload）会自动重新生成 OpenAPI spec。如果配置了 openapi.tagGroups，显式 x-tagGroups 会随 spec 一起再次输出：

路由文件变更 → 触发热重载

创建新的 adapter 实例

重新加载路由 + 收集路由元信息

重新生成 OpenAPI spec（配置了 tagGroups 时包含显式 x-tagGroups）

在新 adapter 上重新注册 /docs 和 /openapi.json 端点

路由变更后的新 spec 会包含当前配置的扩展；这不会让内置侧栏按 tagGroups 重排。修改配置文件时则遵循配置变更的重启流程，不能把路由 soft reload 当作配置热更新。

完整示例

以下是完整的订单路由文件，不是独立可运行项目。需先按 认证与安全 注册 auth，并实现 order Service：findAll(auth, filters) 返回 { items, total }，create(auth, data) 和 cancel(auth, id, reason) 必须检查当前身份、资源归属与业务状态。req.auth 由认证链建立；仅声明 OpenAPI security 不会验证凭据。本页开头的两文件示例用于独立验证文档生成。

// src/routes/orders.ts


export default defineRoutes((app) => {
  // 获取订单列表
  app.get(
    "/",
    {
      validate: {
        query: {
          page: "integer:1-1000?",
          limit: "integer:1-50",
          status: "pending|paid|shipped|completed|cancelled",
          startDate: "date?",
          endDate: "date?",
        },
      },
      docs: {
        summary: "获取订单列表",
        description: "分页获取当前用户的订单列表，支持按状态和日期范围筛选。",
        responses: {
          200: {
            description: "订单列表",
            headers: {
              "X-Total-Count": {
                description: "总订单数",
                schema: { type: "integer" },
              },
            },
          },
        },
      },
      middlewares: ["auth"],
      auth: { required: true, security: "bearerAuth" },
    },
    async (req, res) => {
      const filters = req.valid("query");
      const { items, total } = await app.services.order.findAll(
        req.auth,
        filters,
      );
      res.setHeader("X-Total-Count", String(total));
      res.json(items);
    },
  );

  // 创建订单
  app.post(
    "/",
    {
      validate: {
        body: {
          productId: "string!",
          quantity: "integer:1-99!",
          shippingAddress: "string:1-200!",
          couponCode: "string?",
        },
      },
      docs: {
        summary: "创建订单",
        responses: {
          201: {
            description: "订单创建成功",
            example: {
              orderId: "ord_abc123",
              status: "pending",
              total: 99.99,
            },
          },
          400: { description: "库存不足或优惠券无效" },
          401: { description: "未认证" },
        },
      },
      middlewares: ["auth"],
      auth: { required: true, security: "bearerAuth" },
    },
    async (req, res) => {
      const data = req.valid("body");
      const order = await app.services.order.create(req.auth, data);
      res.json(order, 201);
    },
  );

  // 取消订单
  app.post(
    "/:id/cancel",
    {
      validate: {
        param: { id: "string!" },
        body: { reason: "string:1-500?" },
      },
      docs: {
        summary: "取消订单",
        responses: {
          200: { description: "取消成功" },
          400: { description: "订单状态不允许取消" },
          404: { description: "订单不存在" },
        },
      },
      middlewares: ["auth"],
      auth: { required: true, security: "bearerAuth" },
    },
    async (req, res) => {
      const { id } = req.valid("param");
      const { reason } = req.valid("body");
      await app.services.order.cancel(req.auth, id, reason);
      res.json({ success: true });
    },
  );
});

内置界面资产

内置 renderer 与官网共用同一套 Vext 标记几何、青绿/青色 light/dark theme token、绿色/琥珀色标记辅色和 favicon。即使自定义 docs 路径，这些资产仍由 Vext 内置并保持一致，应用无需另装 OpenAPI UI 包。

